800	    function cl_fix_from_real(a : real; result_fmt : FixFormat_t; saturate : FixSaturate_t := SatWarn_s) return std_logic_vector is
801	        -- Several toolchains have bugs in ieee.math_real."mod" (Vivado, Efinity, Gowin EDA).
802	        -- Therefore, this local function is used as a workaround.
803	        function real_mod(a, b : real) return real is
804	        begin
805	            return a - b * floor(a/b);
806	        end function;
807	        
808	        constant ChunkSize_c    : positive := 30;
809	        constant ChunkCount_c   : positive := (cl_fix_width(result_fmt) + ChunkSize_c - 1)/ChunkSize_c;
810	        variable ASat_v         : real;
811	        variable Chunk_v        : std_logic_vector(ChunkSize_c-1 downto 0);
812	        variable Result_v       : std_logic_vector(ChunkSize_c*ChunkCount_c-1 downto 0);
813	    begin
814	        -- Saturation is mandatory in this function (because wrapping has not been implemented)
815	        assert saturate = SatWarn_s or saturate = Sat_s
816	            report "cl_fix_for_real: Saturation mode must be SatWarn_s or Sat_s"
817	            severity Failure;
818	            
819	        -- Saturate
820	        if a > max_real(result_fmt) then
821	            assert saturate = Sat_s report "cl_fix_from_real : Saturation warning!" severity Warning;
822	            ASat_v := max_real(result_fmt);
823	        elsif a < min_real(result_fmt) then
824	            assert saturate = Sat_s report "cl_fix_from_real : Saturation warning!" severity Warning;
825	            ASat_v := min_real(result_fmt);
826	        else
827	            ASat_v := a;
828	        end if;
829	        
830	        -- Rescale to appropriate fractional bits, with half-up rounding
831	        ASat_v := floor(ASat_v * 2.0**result_fmt.F + 0.5);
832	        
833	        -- Convert to fixed-point in chunks (required for formats that don't fit into integer)
834	        for i in 0 to ChunkCount_c-1 loop
835	            Chunk_v := std_logic_vector(to_unsigned(integer(real_mod(ASat_v, 2.0**ChunkSize_c)), ChunkSize_c));
836	            Result_v((i+1)*ChunkSize_c-1 downto i*ChunkSize_c) := Chunk_v;
837	            ASat_v := floor(ASat_v/2.0**ChunkSize_c);
838	        end loop;
839	        
840	        return Result_v(cl_fix_width(result_fmt)-1 downto 0);
841	    end;
842	    
843	    function cl_fix_to_real(a : std_logic_vector; a_fmt : FixFormat_t) return real is
844	        constant ABits_c        : natural := cl_fix_width(a_fmt);
845	        constant ChunkSize_c    : positive := 30;
846	        constant ChunkCount_c   : natural := (ABits_c + ChunkSize_c - 1)/ChunkSize_c;
847	        variable a_v            : std_logic_vector(a'length-1 downto 0);
848	        variable Correction_v   : real := 0.0;
849	        variable apad_v         : unsigned(ChunkSize_c*ChunkCount_c-1 downto 0);
850	        variable Chunk_v        : unsigned(ChunkSize_c-1 downto 0);
851	        variable result_v       : real := 0.0;
852	    begin
853	        -- Enforce 'downto' bit order
854	        a_v := a;
855	        
856	        -- Handle sign bit
857	        if a_fmt.S = 1 and a_v(ABits_c-1) = '1' then
858	            a_v(ABits_c-1) := '0'; -- Clear sign bit.
859	            Correction_v := -2.0**(ABits_c-1 - a_fmt.F); -- Remember its weight.
860	        end if;
861	        
862	        -- Resize to an integer number of chunks
863	        apad_v := resize(unsigned(a_v), ChunkSize_c*ChunkCount_c);
864	        
865	        -- Convert to real in chunks
866	        for i in ChunkCount_c-1 downto 0 loop
867	            result_v := result_v * 2.0**ChunkSize_c; -- Shift to next chunk.
868	            Chunk_v := apad_v((i+1)*ChunkSize_c-1 downto i*ChunkSize_c);
869	            result_v := result_v + real(to_integer(Chunk_v)) * 2.0**(-a_fmt.F);
870	        end loop;
871	        
872	        -- Add sign bit contribution
873	        result_v := result_v + Correction_v;
874	        
875	        return result_v;
876	    end;
