878	    function cl_fix_from_integer(a : integer; aFmt : FixFormat_t) return std_logic_vector is
879	    begin
880	        if aFmt.S = 1 then
881	            return std_logic_vector(to_signed(a, cl_fix_width(aFmt)));
882	        else
883	            return std_logic_vector(to_unsigned(a, cl_fix_width(aFmt)));
884	        end if;
885	    end function;
