912	    function cl_fix_round(
913	        a           : std_logic_vector;
914	        a_fmt       : FixFormat_t;
915	        result_fmt  : FixFormat_t;
916	        round       : FixRound_t := Trunc_s;
917	        fmt_check   : boolean := true
918	    ) return std_logic_vector is
919	        -- Force downto 0
920	        constant a_c            : std_logic_vector(cl_fix_width(a_fmt)-1 downto 0) := a;
921	        
922	        -- The result format takes care of potential integer growth due to the rounding mode.
923	        -- In the intermediate calculation, we need to +/- up to 2.0**-(result_fmt.F+1) in order to
924	        -- implement each rounding algorithm (except trivial Trunc_s). To keep life simple, we just
925	        -- force at least result_fmt.F+1 frac bits (even if this is sometimes one too many). The
926	        -- synthesis tool is likely to optimize this fine.
927	        constant mid_fmt_c      : FixFormat_t := (
928	            result_fmt.S,
929	            result_fmt.I,
930	            maximum(result_fmt.F+1, a_fmt.F)
931	        );
932	        constant in_offset_c    : natural := mid_fmt_c.F - a_fmt.F;
933	        constant out_offset_c   : natural := mid_fmt_c.F - result_fmt.F;
934	        constant half_c         : unsigned(cl_fix_width(mid_fmt_c)-1 downto 0) := get_half(mid_fmt_c, result_fmt);
935	        constant sign_c         : std_logic := cl_fix_sign(a_c, a_fmt);
936	        variable unit_v         : std_logic;
937	        variable mid_v          : unsigned(cl_fix_width(mid_fmt_c)-1 downto 0) := (others => '0');
938	        variable result_v       : std_logic_vector(cl_fix_width(result_fmt)-1 downto 0);
939	    begin
940	        -- Allow the designer to ignore the worst-case result format (with caution).
941	        if fmt_check then
942	            assert result_fmt = cl_fix_round_fmt(a_fmt, result_fmt.F, round)
943	                report "cl_fix_round: Invalid result format. Use cl_fix_round_fmt()." severity Failure;
944	        end if;
945	        
946	        -- Write the input value into mid_v with correct binary point alignment.
947	        mid_v := unsigned(convert(a_c, a_fmt, mid_fmt_c));
948	        
949	        -- To implement each rounding algorithm, we add an appropriate offset before truncating.
950	        if result_fmt.F < a_fmt.F then
951	            
952	            -- Get the least significant bit in the result format (for convergent rounding)
953	            unit_v := get_unit_bit(std_logic_vector(mid_v), mid_fmt_c, result_fmt);
954	            
955	            case round is
956	                when Trunc_s =>
957	                    null;  -- Crude truncation => no offset.
958	                when NonSymPos_s =>
959	                    mid_v := mid_v + half_c;
960	                when NonSymNeg_s =>
961	                    mid_v := mid_v + (half_c-1);
962	                when SymInf_s =>
963	                    mid_v := mid_v + half_c - ("" & sign_c);
964	                when SymZero_s =>
965	                    mid_v := mid_v + half_c - ("" & not sign_c);
966	                when ConvEven_s =>
967	                    mid_v := mid_v + half_c - ("" & not unit_v);
968	                when ConvOdd_s =>
969	                    mid_v := mid_v + half_c - ("" & unit_v);
970	                when others => report "Unrecognized rounding mode: " & to_string(round) severity Failure;
971	            end case;
972	        end if;
973	        
974	        -- Truncate (and force downto 0 by assigning to result_v before returning)
975	        result_v := std_logic_vector(mid_v(cl_fix_width(result_fmt)+out_offset_c-1 downto out_offset_c));
976	        
977	        return result_v;
978	    end;
979	    
980	    function cl_fix_saturate(
981	        a           : std_logic_vector;
982	        a_fmt       : FixFormat_t;
983	        result_fmt  : FixFormat_t;
984	        saturate    : FixSaturate_t := Warn_s
985	    ) return std_logic_vector is
986	        variable result_v   : std_logic_vector(cl_fix_width(result_fmt)-1 downto 0);
987	    begin
988	        assert result_fmt.F = a_fmt.F report "cl_fix_saturate: Number of frac bits cannot change." severity Failure;
989	        
990	        -- Saturation warning
991	        if saturate = Warn_s or saturate = SatWarn_s then
992	            assert cl_fix_in_range(a, a_fmt, result_fmt)
993	                report "cl_fix_saturate : Saturation warning!" severity Warning;
994	        end if;
995	        
996	        -- Write the input value into result_v with correct binary point alignment.
997	        result_v := convert(a, a_fmt, result_fmt);
998	        
999	        -- Saturate
1000	        if saturate = Sat_s or saturate = SatWarn_s then
1001	            if cl_fix_compare("<", a, a_fmt, cl_fix_min_value(result_fmt), result_fmt) then
1002	                result_v := cl_fix_min_value(result_fmt);
1003	            elsif cl_fix_compare(">", a, a_fmt, cl_fix_max_value(result_fmt), result_fmt) then
1004	                result_v := cl_fix_max_value(result_fmt);
1005	            end if;
1006	        end if;
1007	        
1008	        return result_v;
1009	    end;
1010	    
1011	    function cl_fix_resize(
1012	        a           : std_logic_vector;
1013	        a_fmt       : FixFormat_t;
1014	        result_fmt  : FixFormat_t;
1015	        round       : FixRound_t    := Trunc_s;
1016	        saturate    : FixSaturate_t := Warn_s
1017	    ) return std_logic_vector is
1018	        -- Round
1019	        constant rounded_fmt_c  : FixFormat_t := cl_fix_round_fmt(a_fmt, result_fmt.F, round);
1020	        constant rounded_c      : std_logic_vector := cl_fix_round(a, a_fmt, rounded_fmt_c, round);
1021	    begin
1022	        -- Saturate
1023	        return cl_fix_saturate(rounded_c, rounded_fmt_c, result_fmt, saturate);
1024	    end;
1025	    
1026	    function cl_fix_in_range(
1027	        a           : std_logic_vector;
1028	        a_fmt       : FixFormat_t;
1029	        result_fmt  : FixFormat_t;
1030	        round       : FixRound_t := Trunc_s
1031	    ) return boolean is
1032	        -- Note: If result_fmt.F /= a_fmt.F, then we need to know what rounding algorithm will be
1033	        --       used when reducing the LSBs.
1034	        constant rndFmt_c : FixFormat_t := cl_fix_round_fmt(a_fmt, result_fmt.F, round);
1035	        
1036	        -- Apply rounding
1037	        constant Rounded_c  : std_logic_vector := cl_fix_round(to01(a), a_fmt, rndFmt_c, round);
1038	    begin
1039	        return cl_fix_compare(">=", Rounded_c, rndFmt_c, cl_fix_min_value(result_fmt), result_fmt) and
1040	               cl_fix_compare("<=", Rounded_c, rndFmt_c, cl_fix_max_value(result_fmt), result_fmt);
1041	    end;
1042	    
1043	    function cl_fix_recommended_pipelining(
1044	        a_fmt       : FixFormat_t;
1045	        result_fmt  : FixFormat_t;
1046	        round       : FixRound_t;
1047	        fmt_check   : boolean := true
1048	    ) return natural is
1049	    begin
1050	        -- Allow the designer to ignore the worst-case result format (with caution).
1051	        if fmt_check then
1052	            assert result_fmt = cl_fix_round_fmt(a_fmt, result_fmt.F, round)
1053	                report "cl_fix_recommended_pipelining: Invalid result format. Use cl_fix_round_fmt()." severity Failure;
1054	        end if;
1055	        
1056	        -- Registering is not needed if zero logic is used. This happens in two cases:
1057	        -- (1) During truncation.
1058	        if round = Trunc_s then
1059	            return 0;
1060	        else
1061	            -- If a new rounding mode is defined, then appropriate behavior must be implemented.
1062	            assert round = NonSymPos_s or round = NonSymNeg_s or round = SymInf_s or round = SymZero_s or round = ConvEven_s or round = ConvOdd_s
1063	                report "cl_fix_recommended_pipelining: Unhandled rounding mode."
1064	                severity Failure;
1065	        end if;
1066	        -- (2) If the number of fractional bits isn't being decreased.
1067	        if result_fmt.F >= a_fmt.F then
1068	            return 0;
1069	        end if;
1070	        return 1;
1071	    end;
1072	    
1073	    function cl_fix_recommended_pipelining(
1074	        a_fmt       : FixFormat_t;
1075	        result_fmt  : FixFormat_t;
1076	        saturate    : FixSaturate_t
1077	    ) return natural is
1078	    begin
1079	        assert result_fmt.F = a_fmt.F
1080	            report "cl_fix_recommended_pipelining: Number of frac bits cannot change during saturation."
1081	            severity Failure;
1082	        
1083	        -- Registering is not needed if zero logic is used. This happens in two cases:
1084	        -- (1) During wrapping.
1085	        if saturate = None_s or saturate = Warn_s then
1086	            return 0;
1087	        else
1088	            -- If a new saturation mode is defined, then appropriate behavior must be implemented.
1089	            assert saturate = Sat_s or saturate = SatWarn_s
1090	                report "cl_fix_recommended_pipelining: Unhandled saturation mode."
1091	                severity Failure;
1092	        end if;
1093	        -- (2) If the number of integer bits is not being decreased, and the number of sign bits is
1094	        --     not being changed.
1095	        if result_fmt.I >= a_fmt.I and result_fmt.S = a_fmt.S then
1096	            return 0;
1097	        end if;
1098	        return 1;
1099	    end;
1100	    
1101	    function cl_fix_recommended_pipelining(
1102	        a_fmt       : FixFormat_t;
1103	        result_fmt  : FixFormat_t;
1104	        round       : FixRound_t;
1105	        saturate    : FixSaturate_t
1106	    ) return natural is
1107	        constant round_fmt_c    : FixFormat_t := cl_fix_round_fmt(a_fmt, result_fmt.F, round);
1108	    begin
1109	        return cl_fix_recommended_pipelining(a_fmt, round_fmt_c, round)
1110	             + cl_fix_recommended_pipelining(round_fmt_c, result_fmt, saturate);
1111	    end;
1112	    
1113	    function cl_fix_abs(
1114	        a           : std_logic_vector;
1115	        a_fmt       : FixFormat_t;
1116	        result_fmt  : FixFormat_t := NullFixFormat_c;
1117	        round       : FixRound_t := Trunc_s;
1118	        saturate    : FixSaturate_t := Warn_s
1119	    ) return std_logic_vector is
1120	        constant mid_fmt_c  : FixFormat_t := cl_fix_abs_fmt(a_fmt);
1121	        constant r_fmt_c    : FixFormat_t := choose(result_fmt = NullFixFormat_c, mid_fmt_c, result_fmt);
1122	        variable mid_v      : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1123	    begin
1124	        if cl_fix_sign(a, a_fmt) = '1' then
1125	            mid_v := cl_fix_neg(a, a_fmt, mid_fmt_c);
1126	        else
1127	            mid_v := convert(a, a_fmt, mid_fmt_c);
1128	        end if;
1129	        return cl_fix_resize(mid_v, mid_fmt_c, r_fmt_c, round, saturate);
1130	    end;
1131	    
1132	    function cl_fix_neg(
1133	        a           : std_logic_vector;
1134	        a_fmt       : FixFormat_t;
1135	        result_fmt  : FixFormat_t := NullFixFormat_c;
1136	        round       : FixRound_t := Trunc_s;
1137	        saturate    : FixSaturate_t := Warn_s
1138	    ) return std_logic_vector is
1139	        constant mid_fmt_c  : FixFormat_t := cl_fix_neg_fmt(a_fmt);
1140	        constant r_fmt_c    : FixFormat_t := choose(result_fmt = NullFixFormat_c, mid_fmt_c, result_fmt);
1141	        variable a_v        : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1142	        variable mid_v      : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1143	    begin
1144	        a_v := convert(a, a_fmt, mid_fmt_c);
1145	        mid_v := std_logic_vector(-signed(a_v));
1146	        return cl_fix_resize(mid_v, mid_fmt_c, r_fmt_c, round, saturate);
1147	    end;
1148	    
1149	    function cl_fix_add(
1150	        a           : std_logic_vector;
1151	        a_fmt       : FixFormat_t;
1152	        b           : std_logic_vector;
1153	        b_fmt       : FixFormat_t;
1154	        result_fmt  : FixFormat_t := NullFixFormat_c;
1155	        round       : FixRound_t := Trunc_s;
1156	        saturate    : FixSaturate_t := Warn_s
1157	    ) return std_logic_vector is
1158	        constant mid_fmt_c  : FixFormat_t := cl_fix_add_fmt(a_fmt, b_fmt);
1159	        constant r_fmt_c    : FixFormat_t := choose(result_fmt = NullFixFormat_c, mid_fmt_c, result_fmt);
1160	        variable a_v        : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1161	        variable b_v        : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1162	        variable mid_v      : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1163	    begin
1164	        a_v := convert(a, a_fmt, mid_fmt_c);
1165	        b_v := convert(b, b_fmt, mid_fmt_c);
1166	        -- Signed/unsigned addition/subtraction are identical when using two's complement.
1167	        -- However, a long-standing Vivado bug causes incorrect post-synthesis behavior in DSP
1168	        -- slices (pre-add or post-add) if numeric_std.unsigned is used. There are no known issues
1169	        -- for numeric_std.signed, so we always use that.
1170	        mid_v := std_logic_vector(signed(a_v) + signed(b_v));
1171	        return cl_fix_resize(mid_v, mid_fmt_c, r_fmt_c, round, saturate);
1172	    end;
1173	    
1174	    function cl_fix_sub(
1175	        a           : std_logic_vector;
1176	        a_fmt       : FixFormat_t;
1177	        b           : std_logic_vector;
1178	        b_fmt       : FixFormat_t;
1179	        result_fmt  : FixFormat_t := NullFixFormat_c;
1180	        round       : FixRound_t := Trunc_s;
1181	        saturate    : FixSaturate_t := Warn_s
1182	    ) return std_logic_vector is
1183	        constant mid_fmt_c  : FixFormat_t := cl_fix_sub_fmt(a_fmt, b_fmt);
1184	        constant r_fmt_c    : FixFormat_t := choose(result_fmt = NullFixFormat_c, mid_fmt_c, result_fmt);
1185	        variable a_v        : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1186	        variable b_v        : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1187	        variable mid_v      : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1188	    begin
1189	        a_v := convert(a, a_fmt, mid_fmt_c);
1190	        b_v := convert(b, b_fmt, mid_fmt_c);
1191	        -- Signed/unsigned addition/subtraction are identical when using two's complement.
1192	        -- However, a long-standing Vivado bug causes incorrect post-synthesis behavior in DSP
1193	        -- slices (pre-add or post-add) if numeric_std.unsigned is used. There are no known issues
1194	        -- for numeric_std.signed, so we always use that.
1195	        mid_v := std_logic_vector(signed(a_v) - signed(b_v));
1196	        return cl_fix_resize(mid_v, mid_fmt_c, r_fmt_c, round, saturate);
1197	    end;
1198	    
1199	    function cl_fix_addsub(
1200	        a           : std_logic_vector;
1201	        a_fmt       : FixFormat_t;
1202	        b           : std_logic_vector;
1203	        b_fmt       : FixFormat_t;
1204	        add         : std_logic;
1205	        result_fmt  : FixFormat_t := NullFixFormat_c;
1206	        round       : FixRound_t := Trunc_s;
1207	        saturate    : FixSaturate_t := Warn_s
1208	    ) return std_logic_vector is
1209	    begin
1210	        if to01(add) = '1' then
1211	            return cl_fix_add(a, a_fmt, b, b_fmt, result_fmt, round, saturate);
1212	        end if;
1213	        return cl_fix_sub(a, a_fmt, b, b_fmt, result_fmt, round, saturate);
1214	    end;
1215	    
1216	    function cl_fix_mult(
1217	        a           : std_logic_vector;
1218	        a_fmt       : FixFormat_t;
1219	        b           : std_logic_vector;
1220	        b_fmt       : FixFormat_t;
1221	        result_fmt  : FixFormat_t := NullFixFormat_c;
1222	        round       : FixRound_t := Trunc_s;
1223	        saturate    : FixSaturate_t := Warn_s
1224	    ) return std_logic_vector is
1225	        -- Force downto 0
1226	        constant a_c            : std_logic_vector(cl_fix_width(a_fmt)-1 downto 0) := a;
1227	        constant b_c            : std_logic_vector(cl_fix_width(b_fmt)-1 downto 0) := b;
1228	        
1229	        -- VHDL doesn't define a * operator for mixed signed*unsigned or unsigned*signed.
1230	        -- Just inside cl_fix_mult, it is safe to define them for local use.
1231	        function "*"(x : signed; y : unsigned) return signed is
1232	        begin
1233	            return x * ('0' & signed(y));
1234	        end function;
1235	        
1236	        function "*"(x : unsigned; y : signed) return signed is
1237	        begin
1238	            return y * x;
1239	        end function;
1240	        
1241	        constant mid_fmt_c      : FixFormat_t := cl_fix_mult_fmt(a_fmt, b_fmt);
1242	        constant r_fmt_c        : FixFormat_t := choose(result_fmt = NullFixFormat_c, mid_fmt_c, result_fmt);
1243	        constant mid_width_c    : positive := cl_fix_width(mid_fmt_c);
1244	        variable mid_v          : std_logic_vector(mid_width_c-1 downto 0);
1245	    begin
1246	        if a_fmt.S = 0 and b_fmt.S = 0 then
1247	            mid_v := std_logic_vector(resize(unsigned(a_c) * unsigned(b_c), mid_width_c));
1248	        elsif a_fmt.S = 0 and b_fmt.S = 1 then
1249	            mid_v := std_logic_vector(resize_sensible(unsigned(a_c) * signed(b_c), mid_width_c));
1250	        elsif a_fmt.S = 1 and b_fmt.S = 0 then
1251	            mid_v := std_logic_vector(resize_sensible(signed(a_c) * unsigned(b_c), mid_width_c));
1252	        else
1253	            mid_v := std_logic_vector(resize_sensible(signed(a_c) * signed(b_c), mid_width_c));
1254	        end if;
1255	        
1256	        return cl_fix_resize(mid_v, mid_fmt_c, r_fmt_c, round, saturate);
1257	    end;
1258	    
1259	    function cl_fix_shift(
1260	        a           : std_logic_vector;
1261	        a_fmt       : FixFormat_t;
1262	        shift       : integer;
1263	        result_fmt  : FixFormat_t;
1264	        round       : FixRound_t := Trunc_s;
1265	        saturate    : FixSaturate_t := Warn_s
1266	    ) return std_logic_vector is
1267	        -- Implicitly shift by resizing to a dummy format, then reinterpreting as result_fmt.
1268	        constant dummy_fmt_c  : FixFormat_t := (result_fmt.S, result_fmt.I - shift, result_fmt.F + shift);
1269	    begin
1270	        -- Note: This function performs a lossless shift (equivalent to *2.0**shift), then resizes
1271	        --       to the output format. The initial shift does NOT truncate any bits.
1272	        -- Note: "shift" direction is left. (So shift<0 shifts right).
1273	        return cl_fix_resize(a, a_fmt, dummy_fmt_c, round, saturate);
1274	    end;
1275	    
1276	    function cl_fix_compare(
1277	        comparison  : string;
1278	        a           : std_logic_vector;
1279	        aFmt        : FixFormat_t;
1280	        b           : std_logic_vector;
1281	        bFmt        : FixFormat_t
1282	    ) return boolean is
1283	        constant mid_fmt_c  : FixFormat_t := union(aFmt, bFmt);
1284	        variable a_v        : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1285	        variable b_v        : std_logic_vector(cl_fix_width(mid_fmt_c)-1 downto 0);
1286	    begin
1287	        -- Convert to same type
1288	        a_v := convert(a, aFmt, mid_fmt_c);
1289	        b_v := convert(b, bFmt, mid_fmt_c);
1290	        
1291	        -- Compare
1292	        if mid_fmt_c.S = 1 then
1293	            if    comparison = "="  then return signed(a_v) =  signed(b_v);
1294	            elsif comparison = "!=" then return signed(a_v) /= signed(b_v);
1295	            elsif comparison = "<"  then return signed(a_v) <  signed(b_v);
1296	            elsif comparison = ">"  then return signed(a_v) >  signed(b_v);
1297	            elsif comparison = "<=" then return signed(a_v) <= signed(b_v);
1298	            elsif comparison = ">=" then return signed(a_v) >= signed(b_v);
1299	            else
1300	                report "cl_fix_compare: Unrecognized comparison type: " & comparison severity Failure;
1301	                return false;
1302	            end if;
1303	        else
1304	            if    comparison = "="  then return unsigned(a_v) =  unsigned(b_v);
1305	            elsif comparison = "!=" then return unsigned(a_v) /= unsigned(b_v);
1306	            elsif comparison = "<"  then return unsigned(a_v) <  unsigned(b_v);
1307	            elsif comparison = ">"  then return unsigned(a_v) >  unsigned(b_v);
1308	            elsif comparison = "<=" then return unsigned(a_v) <= unsigned(b_v);
1309	            elsif comparison = ">=" then return unsigned(a_v) >= unsigned(b_v);
1310	            else
1311	                report "cl_fix_compare: Unrecognized comparison type: " & comparison severity Failure;
1312	                return false;
1313	            end if;
1314	        end if;
1315	    end function;
1316	    
1317	    function cl_fix_sign(a : std_logic_vector; aFmt : FixFormat_t) return std_logic is
1318	        -- Force downto 0
1319	        constant a_c    : std_logic_vector(cl_fix_width(aFmt)-1 downto 0) := a;
1320	    begin
1321	        if aFmt.S = 0 or cl_fix_width(aFmt) = 0 then
1322	            return '0';
1323	        end if;
1324	        return a_c(a_c'high);
1325	    end function;
1326	end;
